  function disclosure(label){const details=node('details','profile-section'),summary=node('summary','',label),body=node('div','disclosure-body');details.append(summary,body);return {details,body};}
  function evidenceBlock(candidate,evidence){const block=node('div','evidence-item');block.append(node('span','status-badge',evidence.type?.replace(/-/g,' ')||'Source evidence'));if(evidence.reviewedParaphrase||evidence.sourceQuote&&evidence.sourceQuote!==evidence.text){block.append(node('p','small-label source-proof-label','Reviewed source summary'),node('p','reviewed-source-summary',evidence.text));if(evidence.sourceQuote)block.append(node('p','small-label source-proof-label','Exact supporting passage'),node('blockquote','source-quote',evidence.sourceQuote));}else block.append(node('blockquote','source-quote',evidence.text));const meta=node('p','evidence-meta',`${evidence.sourceLabel||'Stored professional record'} · ${evidence.field||'Profile'}\nSource date: ${evidence.dates?.sourceDate||'Not recorded'} · Observed: ${evidence.dates?.observedAt||'Not recorded'}`);block.append(meta);if(evidence.qualifiers?.length)block.append(node('p','evidence-meta',evidence.qualifiers.join(' · ').replace(/-/g,' ')));for(const limitation of list(evidence.review?.limitations))block.append(node('p','evidence-meta','Source limitation: '+limitation));const link=sourceLink(candidate,evidence);if(link)block.append(link);return block;}
