      const reviews=node('div','review-grid');for(const [field,label,options]of [['qualification','Qualification review',[['not-reviewed','Not reviewed'],['follow-up-needed','Follow-up needed'],['reviewed-by-team','Reviewed by team'],['not-suitable','Not suitable for this scope']]],['independence','Independence review',[['not-reviewed','Not reviewed'],['declaration-requested','Declaration requested'],['team-reviewed','Reviewed by team'],['concern-recorded','Concern recorded']]]]){const wrap=node('div'),id='review-'+field+'-'+c.id,labelNode=node('label','field-label',label),select=node('select');labelNode.htmlFor=id;select.id=id;for(const [value,text]of options){const option=node('option','',text);option.value=value;select.append(option);}select.value=saved[field];select.addEventListener('change',async()=>{try{const ok=await mutateProject(p.id,latest=>P.changeReview(latest,c.id,field,select.value,{actor:'user'}));toast(ok?'Your review decision was recorded for this assessment scope.':'Review held in memory. Export your project now.');}catch(error){toast(error.message);select.value=saved[field];}});wrap.append(labelNode,select);reviews.append(wrap);}card.append(reviews,node('p','review-help','These are your recorded decisions for this scope. They are not automated approval or confirmation of participation.'));
